// Confere o formulário do dono e lê serviços, profissionais e horários POR REGRA (duração e preço não podem sair errados).
let b = $('🔔 Pedido de criação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const sem = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const slug = s => sem(s).replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 34);
const opcao = (v, lista, padrao) => lista.includes(Number(v)) ? Number(v) : padrao;
const crypto = require('crypto');
const erros = [];

// "Corte masculino - 30 min - R$ 35" · "Corte + barba | 1h | 55,00" · "Sobrancelha 15min R$10"
const servicos = String(b.servicos || '').split(/\n|;/).map(l => l.trim()).filter(Boolean).slice(0, 30).map((l, i) => {
  const dur = l.match(/(\d{1,3}(?:[.,]\d)?)\s*(h|hr|hora|horas|min|mins|minutos|m)\b/i);
  const preco = l.match(/R\$\s*([\d.]+(?:,\d{1,2})?)/i) || l.match(/(?:^|[\s|–—-])(\d{1,5}(?:,\d{2}|\.\d{2}))\s*$/);
  let nome = l;
  if (dur) nome = nome.replace(dur[0], ' ');
  if (preco) nome = nome.replace(preco[0], ' ');
  nome = limpa(nome.replace(/[|–—:]+/g, ' ').replace(/\s-\s|\s-$|^-\s/g, ' '), 50).replace(/\s*-\s*$/, '');
  let min = dur ? (/^h/i.test(dur[2]) ? Math.round(parseFloat(dur[1].replace(',', '.')) * 60) : parseInt(dur[1], 10)) : 30;
  min = Math.min(480, Math.max(15, Math.ceil(min / 15) * 15));  // a agenda trabalha em blocos de 15 min
  const valor = preco ? Number(preco[1].replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0 : 0;
  return nome ? { k: 's' + (i + 1), nome, duracao: min, preco: Math.round(valor * 100) / 100 } : null;
}).filter(Boolean);
if (!servicos.length) erros.push('Liste pelo menos 1 serviço (ex.: Corte masculino - 30 min - R$ 35).');

// "Zé: corte, barba" (só esses serviços) · "Léo" (todos)
let profissionais = String(b.profissionais || '').split(/\n|;/).map(l => l.trim()).filter(Boolean).slice(0, 12).map((l, i) => {
  const [n, lista] = l.split(':');
  const nome = limpa(n, 30);
  let ks = servicos.map(s => s.k);
  if (lista && lista.trim()) {
    const pedidos = lista.split(/,|\be\b/).map(x => sem(x).trim()).filter(Boolean);
    const achados = servicos.filter(s => pedidos.some(p => sem(s.nome).includes(p) || p.includes(sem(s.nome))));
    if (achados.length) ks = achados.map(s => s.k);
  }
  return nome ? { k: 'p' + (i + 1), nome, servicos: ks } : null;
}).filter(Boolean);
if (!profissionais.length) profissionais = [{ k: 'p1', nome: 'Equipe', servicos: servicos.map(s => s.k) }];

// horário: um registro por dia da semana (0 = domingo), com pausa opcional
const min = h => +h.slice(0, 2) * 60 + +h.slice(3);
const hh = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
// tudo alinhado na marca de 15 min: as travas são blocos de 15 min e só se cruzam se começarem nas mesmas marcas
const hhmm = (v, sobe) => {
  if (!/^\d{1,2}:\d{2}$/.test(String(v || ''))) return '';
  const m = min(String(v).padStart(5, '0'));
  return m >= 0 && m <= 1440 ? hh(Math.min(1440, sobe ? Math.ceil(m / 15) * 15 : Math.floor(m / 15) * 15)).replace('24:00', '23:45') : '';
};
const horarios = {};
for (let d = 0; d < 7; d++) {
  const h = (b.horarios || {})[d] || {};
  const abre = hhmm(h.abre, true), fecha = hhmm(h.fecha, false), pi = hhmm(h.pausa_ini, false), pf = hhmm(h.pausa_fim, true);
  if (!h.aberto || !abre || !fecha || min(fecha) <= min(abre)) { horarios[d] = []; continue; }
  horarios[d] = pi && pf && min(pi) > min(abre) && min(pf) < min(fecha) && min(pf) > min(pi)
    ? [{ abre, fecha: pi }, { abre: pf, fecha }] : [{ abre, fecha }];
}
if (!Object.values(horarios).some(x => x.length)) erros.push('Marque pelo menos 1 dia de atendimento com horário de abrir e fechar.');

const dados = {
  nome: limpa(b.nome, 60), tipo: limpa(b.tipo, 40), servicos, profissionais, horarios,
  passo: opcao(b.passo, [15, 30, 60], 30), antecedencia_h: opcao(b.antecedencia_h, [0, 1, 2, 4, 12, 24], 2),
  dias_frente: opcao(b.dias_frente, [7, 14, 30, 60], 30), cancelar_ate_h: opcao(b.cancelar_ate_h, [0, 1, 2, 6, 12, 24], 2),
  regras: limpa(b.regras, 300),
  whatsapp: String(b.whatsapp || '').replace(/\D/g, '').slice(0, 15),
  instagram: limpa(b.instagram, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
  endereco: limpa(b.endereco, 200),
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '',
};
if (dados.nome.length < 2) erros.push('Digite o nome do negócio.');
if (dados.whatsapp && dados.whatsapp.length < 10) erros.push('O WhatsApp precisa ter DDD.');
if (dados.whatsapp.length >= 10 && dados.whatsapp.length <= 11) dados.whatsapp = '55' + dados.whatsapp;

const id = (slug(dados.nome) || 'agenda') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(6).toString('hex');
const base = String($('🔔 Pedido de criação (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
const resumo_ia = JSON.stringify({ negocio: dados.nome, ramo: dados.tipo || '(não informado)',
  servicos: servicos.map(s => `${s.nome} (${s.duracao} min${s.preco ? ', R$ ' + s.preco.toFixed(2).replace('.', ',') : ''})`),
  profissionais: profissionais.map(p => p.nome), horario: DIAS.map((n, d) => horarios[d].length ? `${n}: ${horarios[d].map(f => f.abre + '–' + f.fecha).join(' e ')}` : null).filter(Boolean),
  regras_do_dono: dados.regras || '(nenhuma)' }, null, 1);
return [{ json: { valido: erros.length === 0, erros, id, chave, segredo: crypto.randomBytes(16).toString('hex'), dados, resumo_ia,
  chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
  agendar_url: `${base}/agenda/${id}/agendar`, painel_url: `${base}/agenda-painel?id=${id}&chave=${chave}` } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê os textos da redatora e prepara o pedido da revisora (ela confere tudo contra os dados do dono).
const v = $('🧩 Confere o pedido').first().json;
let r = null;
try { r = parseJSON($('🤖 Redatora da agenda').first().json.output); } catch (e) {}
return [{ json: { escreveu: !!r, texto_revisora: 'DADOS DO DONO (a única fonte de verdade):\n' + v.resumo_ia
  + '\n\nTEXTOS DA REDATORA:\n' + (r ? JSON.stringify(r, null, 1) : '(a redatora não respondeu: escreva todos os campos você mesma, seguindo as regras)') } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta o que o dono digitou com os textos revisados. As regras do sistema (prazo de cancelamento, antecedência) saem da configuração, nunca da IA.
const base = $('🧩 Confere o pedido').first().json;
const d = base.dados;
const crypto = require('crypto');
let red = null, rev = null;
try { red = parseJSON($('🤖 Redatora da agenda').first().json.output); } catch (e) {}
try { rev = parseJSON($('🤖 Revisora da agenda').first().json.output); } catch (e) {}
red = red || {}; rev = rev || {};
const txt = (v, max) => String(v ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const campo = k => (rev[k] !== undefined && rev[k] !== '' && rev[k] !== null) ? rev[k] : red[k];
// lembrete precisa citar a hora ({hora}); se a IA esquecer, vale o texto padrão
const aviso = (v, padrao) => (v && v.titulo && v.texto && String(v.texto).includes('{hora}')) ? { titulo: txt(v.titulo, 44), texto: txt(v.texto, 140) } : padrao;
const corOk = c => /^#[0-9a-fA-F]{6}$/.test(c || '');
const regrasSistema = [
  d.cancelar_ate_h ? `Dá para cancelar pelo link da reserva até ${d.cancelar_ate_h} h antes do horário.` : 'Dá para cancelar pelo link da reserva até o horário marcado.',
  d.antecedencia_h ? `Os horários abrem com pelo menos ${d.antecedencia_h} h de antecedência.` : null,
  `A agenda mostra os próximos ${d.dias_frente} dias.`,
].filter(Boolean);
const regrasDono = d.regras && Array.isArray(campo('regras')) ? campo('regras').map(x => txt(x, 110)).filter(Boolean).slice(0, 4) : (d.regras ? [d.regras.slice(0, 110)] : []);
const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
const jwk = privateKey.export({ format: 'jwk' }), pub = publicKey.export({ format: 'jwk' });
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
const palavras = d.nome.split(/\s+/).filter(p => p.length > 2 || /^[A-Z0-9]/.test(p));
const iniciais = ((palavras[0] || d.nome)[0] + (palavras[1] ? palavras[1][0] : (palavras[0] || '').slice(1, 2))).toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9]/g, '') || 'AG';

const programa = {
  id: base.id, chave: base.chave, segredo: base.segredo, criado_em: new Date().toISOString(),
  feito_com_ia: !!red.chamada, revisado: !!(rev.chamada || rev.problemas), problemas_revisao: Array.isArray(rev.problemas) ? rev.problemas.map(p => txt(p, 200)).slice(0, 10) : [],
  nome: d.nome, nome_curto: txt(campo('nome_curto'), 12) || d.nome.slice(0, 12), tipo: d.tipo, emoji: txt(campo('emoji'), 4) || '📅',
  cor: corOk(d.cor) ? d.cor : (corOk(campo('cor')) ? campo('cor') : '#1d4ed8'), iniciais: iniciais.slice(0, 2),
  servicos: d.servicos, profissionais: d.profissionais, horarios: d.horarios,
  passo: d.passo, antecedencia_h: d.antecedencia_h, dias_frente: d.dias_frente, cancelar_ate_h: d.cancelar_ate_h,
  textos: {
    chamada: txt(campo('chamada'), 70) || `Agende seu horário na ${d.nome}`,
    boas_vindas: txt(campo('boas_vindas'), 180) || 'Escolha o serviço, o dia e o horário. Leva menos de 1 minuto.',
    confirmacao: txt(campo('confirmacao'), 200) || 'Tudo certo! Seu horário está reservado. Te esperamos!',
    regras: regrasSistema.concat(regrasDono),
    lembrete_24h: aviso(campo('lembrete_24h'), { titulo: '📅 Amanhã é dia!', texto: '{nome}, seu horário de {servico} é amanhã ({dia}) às {hora} com {prof}.' }),
    lembrete_2h: aviso(campo('lembrete_2h'), { titulo: '⏰ Daqui a pouco!', texto: '{nome}, te esperamos às {hora} para {servico} com {prof}.' }),
  },
  whatsapp: d.whatsapp, instagram: d.instagram, endereco: d.endereco,
  vapid: { publica: b64u(Buffer.concat([Buffer.from([4]), unb(pub.x), unb(pub.y)])), privada: { kty: 'EC', crv: 'P-256', d: jwk.d, x: jwk.x, y: jwk.y } },
};
return [{ json: { id: programa.id, programa: JSON.stringify(programa) } }];

// Horários livres (mesma conta na página, na reserva, no painel e na sugestão de promoção).
// Brasil sem horário de verão: Brasília = UTC-3 fixo.
const AG_BLOCO = 15;
const agMin = h => +String(h).slice(0, 2) * 60 + +String(h).slice(3, 5);
const agHH = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const agSemana = dia => new Date(dia + 'T12:00:00Z').getUTCDay();          // 0 = domingo
const agMs = (dia, hora) => Date.parse(`${dia}T${hora}:00-03:00`);
const agHoje = ms => new Date(ms - 3 * 3600000).toISOString().slice(0, 10);
const agSoma = (dia, n) => new Date(Date.parse(dia + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
// blocos de 15 min que um atendimento ocupa ("0900", "0915"...)
function agBlocos(hora, duracao) { const m = agMin(hora), r = []; for (let x = m; x < m + duracao; x += AG_BLOCO) r.push(agHH(x).replace(':', '')); return r; }
// ocupados: { "<prof>": Set("0900", ...) } lidos das travas do dia
function agOcupados(travas, id, dia) {
  const o = {};
  Object.keys(travas || {}).forEach(k => {
    const m = k.match(/^agl:([a-z0-9-]+):(p\d+):(\d{4}-\d{2}-\d{2}):(\d{4})$/);
    if (m && m[1] === id && m[3] === dia && Number(travas[k]) >= 1) (o[m[2]] = o[m[2]] || new Set()).add(m[4]);
  });
  return o;
}
// começos livres para um profissional: dentro do expediente, cabendo a duração inteira, sem pisar em bloco ocupado e com a antecedência mínima
function agLivres(prog, pk, dia, duracao, ocupados, agoraMs) {
  const oc = ocupados[pk] || new Set(), saida = [];
  if (dia < agHoje(agoraMs) || dia > agSoma(agHoje(agoraMs), prog.dias_frente)) return saida;
  for (const f of prog.horarios[agSemana(dia)] || []) {
    for (let m = agMin(f.abre); m + duracao <= agMin(f.fecha); m += prog.passo) {
      if (agMs(dia, agHH(m)) < agoraMs + prog.antecedencia_h * 3600000) continue;
      if (agBlocos(agHH(m), duracao).every(b => !oc.has(b))) saida.push(agHH(m));
    }
  }
  return saida;
}
// quem faz o serviço
const agProfsDo = (prog, sk) => prog.profissionais.filter(p => p.servicos.includes(sk));

// Cores derivadas da cor do negócio, com contraste garantido no tema claro e no escuro.
function agCores(C) {
  const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
  const paraHex = a => '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
  const mistura = (c, alvo, t) => paraHex(hex(c).map((v, i) => v + (alvo[i] - v) * t));
  const lum = c => { const [r, g, b] = hex(c).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
  const contraste = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
  const legivel = (fundo, para, alvo = 4.5) => { let x = C; for (let t = 0.05; t <= 1.01 && contraste(x, fundo) < alvo; t += 0.05) x = mistura(C, para, t); return x; };
  const botaoEscuro = contraste(C, '#1b1b1d') < 3 ? legivel('#1b1b1d', [255, 255, 255], 8) : C;
  return { C, texto: lum(C) > 0.45 ? '#111111' : '#ffffff', C2: mistura(C, [0, 0, 0], 0.35), CL: mistura(C, [255, 255, 255], 0.88), CLd: mistura(C, [0, 0, 0], 0.6),
    claro: legivel('#ffffff', [0, 0, 0]), escuro: legivel('#1b1b1d', [255, 255, 255]), botaoEscuro, textoBotaoEscuro: lum(botaoEscuro) > 0.45 ? '#111111' : '#ffffff',
    barraClaro: legivel('#ffffff', [0, 0, 0], 3), barraEscuro: legivel('#1b1b1d', [255, 255, 255], 3) };
}
const agEsc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const agBRL = n => n ? Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : '';
function agNaoAchou(titulo, texto, codigo = 404) {
  return [{ json: { codigo, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${titulo}</title><meta name="robots" content="noindex"></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px">
<div><div style="font-size:56px">📅</div><h1 style="font-size:22px">${titulo}</h1><p style="color:#666">${texto}</p></div></body></html>` } }];
}

// Página de agendar (o link que o dono divulga). Mostra os dias abertos; os horários livres vêm da API na hora.
let p = null;
try { p = JSON.parse($('📖 Lê a agenda (página)').first().json.programa || 'null'); } catch (e) {}
if (!p) return agNaoAchou('Agenda não encontrada', 'Confira o link que você recebeu.');
const k = agCores(p.cor);
const agora = Date.now(), hoje = agHoje(agora);
const SEM = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'];
const dias = [];
for (let i = 0; i <= p.dias_frente; i++) {
  const d = agSoma(hoje, i);
  if ((p.horarios[agSemana(d)] || []).length) dias.push({ dia: d, rot: i === 0 ? 'Hoje' : i === 1 ? 'Amanhã' : SEM[agSemana(d)], dm: d.slice(8, 10) + '/' + d.slice(5, 7) });
}
const mapa = p.endereco ? 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(p.endereco) : '';

// roda no celular do cliente
function pagina(P) {
  var el = function (s) { return document.querySelector(s); };
  var API = '/webhook/agenda-api', CH = 'ag-' + P.id, st = { servico: null, prof: '*', dia: null, hora: null };
  var qs = new URLSearchParams(location.search);
  var esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); };
  var brl = function (n) { return n ? Number(n).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }) : ''; };
  var dm = function (d) { return d.slice(8, 10) + '/' + d.slice(5, 7); };
  var hoje = new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 10);
  function toast(t, longo) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, longo ? 6000 : 3500); }
  function api(d) {
    return fetch(API, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: P.id }, d)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão agora. Tente de novo.' }; });
  }
  function minhas() { try { return JSON.parse(localStorage.getItem(CH) || '[]'); } catch (e) { return []; } }
  function guardaMinha(r) { var l = minhas().filter(function (x) { return x.codigo !== r.codigo; }); l.unshift(r); try { localStorage.setItem(CH, JSON.stringify(l.slice(0, 10))); } catch (e) {} }
  function mostraMinhas() {
    var l = minhas().filter(function (x) { return x.dia >= hoje; });
    el('#minhas').hidden = !l.length;
    el('#minhas-lista').innerHTML = l.map(function (x) { return '<li><a href="reserva?c=' + x.codigo + '&t=' + x.token + '">📅 ' + dm(x.dia) + ' às ' + x.hora + ' · ' + esc(x.servico) + '</a></li>'; }).join('');
  }
  mostraMinhas();
  function servico() { return P.servicos.filter(function (s) { return s.k === st.servico; })[0]; }
  function passo(n) { [3, 4, 5].forEach(function (i) { el('#passo' + i).hidden = i > n; }); }
  function marca(sel, attr, val) { document.querySelectorAll(sel).forEach(function (b) { b.classList.toggle('on', b.getAttribute(attr) === val); }); }

  // 1 · serviço
  el('#servicos').innerHTML = P.servicos.map(function (s) {
    return '<button class="opc" data-s="' + s.k + '"><b>' + esc(s.nome) + '</b><small>⏱️ ' + s.duracao + ' min' + (s.preco ? ' · ' + brl(s.preco) : '') + '</small></button>';
  }).join('');
  el('#servicos').addEventListener('click', function (e) {
    var b = e.target.closest('[data-s]'); if (!b) return;
    st.servico = b.dataset.s; st.hora = null; marca('#servicos [data-s]', 'data-s', st.servico);
    var profs = P.profissionais.filter(function (p) { return p.servicos.indexOf(st.servico) > -1; });
    st.prof = profs.length === 1 ? profs[0].k : '*';
