try { res = JSON.parse($('📖 Lê a reserva').first().json.reserva || 'null'); } catch (e) {}
const travas = $('🗂️ Lê as travas do dia').first().json || {};
const agora = Date.now();
const sets = [], solta = [], somas = [], travar = [];
const sai = (rota, codigo, corpo, extra = {}) => [{ json: { rota, codigo, resposta: JSON.stringify(corpo), sets, solta, somas, travar, id: P.id, hoje: agHoje(agora), ...extra } }];
