  } catch (e) { return null; }
}

if (P.acao === 'horarios') {
  if (!serv || !P.dia) return erro('Escolha o serviço e o dia.');
  const mapa = {};
  agProfsDo(prog, serv.k).filter(p => P.prof === '*' || p.k === P.prof)
    .forEach(p => agLivres(prog, p.k, P.dia, serv.duracao, ocup, agora).forEach(h => { (mapa[h] = mapa[h] || []).push(p.k); }));
  return sai('responder', 200, { ok: true, dia: P.dia, servico: serv.k, horarios: Object.keys(mapa).sort().map(h => ({ hora: h, profs: mapa[h] })) });
}

if (P.acao === 'reservar') {
  if (!serv) return erro('Escolha um serviço.');
