    prof: prof.k, prof_nome: prof.nome, cliente: { nome: P.nome, fone: P.fone }, status: 'confirmada', criado: agora, sub: subOk(P.sub), lembrou24: false, lembrou2: false };
  const ttl = ateFimDoDia(P.dia) + 86400;
