// desfaz só os blocos que pegamos (n = 1); os outros são de quem chegou antes
return [{ json: { ok: false, soltar: r.filter(x => x.n === 1 && x.chave).map(x => x.chave) } }];

const d = $('📅 Decide a agenda').first().json;
const l = (d.sets || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : []).map(x => ({ json: x }));

