</body></html>`;
return [{ json: { codigo: 200, html } }];

// Horários livres (mesma conta na página, na reserva, no painel e na sugestão de promoção).
// Brasil sem horário de verão: Brasília = UTC-3 fixo.
const AG_BLOCO = 15;
const agMin = h => +String(h).slice(0, 2) * 60 + +String(h).slice(3, 5);
const agHH = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const agSemana = dia => new Date(dia + 'T12:00:00Z').getUTCDay();          // 0 = domingo
const agMs = (dia, hora) => Date.parse(`${dia}T${hora}:00-03:00`);
const agHoje = ms => new Date(ms - 3 * 3600000).toISOString().slice(0, 10);
const agSoma = (dia, n) => new Date(Date.parse(dia + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
// blocos de 15 min que um atendimento ocupa ("0900", "0915"...)
function agBlocos(hora, duracao) { const m = agMin(hora), r = []; for (let x = m; x < m + duracao; x += AG_BLOCO) r.push(agHH(x).replace(':', '')); return r; }
// ocupados: { "<prof>": Set("0900", ...) } lidos das travas do dia
function agOcupados(travas, id, dia) {
  const o = {};
  Object.keys(travas || {}).forEach(k => {
    const m = k.match(/^agl:([a-z0-9-]+):(p\d+):(\d{4}-\d{2}-\d{2}):(\d{4})$/);
    if (m && m[1] === id && m[3] === dia && Number(travas[k]) >= 1) (o[m[2]] = o[m[2]] || new Set()).add(m[4]);
  });
  return o;
}
// começos livres para um profissional: dentro do expediente, cabendo a duração inteira, sem pisar em bloco ocupado e com a antecedência mínima
function agLivres(prog, pk, dia, duracao, ocupados, agoraMs) {
  const oc = ocupados[pk] || new Set(), saida = [];
  if (dia < agHoje(agoraMs) || dia > agSoma(agHoje(agoraMs), prog.dias_frente)) return saida;
  for (const f of prog.horarios[agSemana(dia)] || []) {
    for (let m = agMin(f.abre); m + duracao <= agMin(f.fecha); m += prog.passo) {
      if (agMs(dia, agHH(m)) < agoraMs + prog.antecedencia_h * 3600000) continue;
      if (agBlocos(agHH(m), duracao).every(b => !oc.has(b))) saida.push(agHH(m));
    }
  }
  return saida;
}
// quem faz o serviço
const agProfsDo = (prog, sk) => prog.profissionais.filter(p => p.servicos.includes(sk));

// Quem precisa de lembrete agora: reserva confirmada, com o lembrete ligado, 24 h antes (amanhã) ou 2 h antes (hoje).
// Não lembra logo depois de marcar (quem marcou há pouco não precisa).
const agora = Date.now();
const todas = Object.assign({}, $('🗂️ Lê as reservas de hoje').first().json || {}, $('🗂️ Lê as reservas de amanhã').first().json || {});
const porAgenda = {};
Object.entries(todas).forEach(([k, v]) => {
  const m = k.match(/^agr:([a-z0-9-]+):(\d{4}-\d{2}-\d{2}):(r\d{8}[a-f0-9]{4})$/);
  if (!m) return;
  let r = null;
  try { r = JSON.parse(v); } catch (e) {}
  if (!r || r.status !== 'confirmada' || !r.sub) return;
  const falta = agMs(r.dia, r.hora) - agora, desde = agora - (r.criado || 0);
  let tipo = null;
  if (falta > 0 && falta <= 2 * 3600000 && !r.lembrou2 && desde > 30 * 60000) tipo = '2h';
  else if (falta > 2.25 * 3600000 && falta <= 24 * 3600000 && !r.lembrou24 && desde > 3600000) tipo = '24h';
  if (tipo) (porAgenda[m[1]] = porAgenda[m[1]] || []).push({ chave: k, r, tipo });
});
return Object.entries(porAgenda).map(([id, lista]) => ({ json: { id, lista } }));

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
function criptografa(sub, texto) {
  const cr = require('crypto');
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = cr.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = cr.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(cr.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = cr.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}
function vapid(prog, endpoint) {
  const cr = require('crypto');
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla); o Code node não tem URL(), então recorto o texto
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = cr.sign('sha256', Buffer.from(cab + '.' + corpo), { key: cr.createPrivateKey({ key: prog.vapid.privada, format: 'jwk' }), dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${prog.vapid.publica}`;
}
// {nome} = primeiro nome do cliente · {faltam} = carimbos que faltam para o prêmio
const pers = (t, c, prog) => String(t || '').replace(/\{nome\}/g, String(c.nome || '').split(' ')[0]).replace(/\{faltam\}/g, Math.max(1, prog.meta - c.carimbos));

// Monta o lembrete de cada reserva com os textos da agenda ({nome}, {servico}, {dia}, {hora}, {prof}) e criptografa para o celular.
const crypto = require('crypto');
const grupos = $('🧩 Separa as agendas com lembrete').all(), progs = $('📖 Lê a agenda (lembrete)').all();
const dm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
const saida = [];
grupos.forEach((g, i) => {
  let prog = null;
  try { prog = JSON.parse((progs[i] || {}).json.programa || 'null'); } catch (e) {}
  if (!prog || !prog.vapid) return;
  g.json.lista.forEach(({ chave, r, tipo }) => {
    const t = prog.textos[tipo === '2h' ? 'lembrete_2h' : 'lembrete_24h'];
    const troca = s => String(s || '').replace(/\{nome\}/g, String(r.cliente.nome).split(' ')[0]).replace(/\{servico\}/g, r.servico_nome)
      .replace(/\{hora\}/g, r.hora).replace(/\{dia\}/g, dm(r.dia)).replace(/\{prof\}/g, r.prof_nome);
    const token = crypto.createHmac('sha256', prog.segredo).update('res:' + r.codigo).digest('hex').slice(0, 20);
    try {  // inscrição com chave quebrada é pulada (não derruba os outros lembretes)
      saida.push({ json: { chave, tipo, reserva: r, endpoint: r.sub.endpoint, autorizacao: vapid(prog, r.sub.endpoint) },
        binary: { corpo: { data: criptografa(r.sub, JSON.stringify({ titulo: troca(t.titulo), texto: troca(t.texto), url: `reserva?c=${r.codigo}&t=${token}`, tag: 'lembrete-' + r.codigo })).toString('base64'),
          mimeType: 'application/octet-stream', fileName: 'lembrete.bin' } } });
    } catch (e) {}
  });
});
return saida;

// 201 = entregue: marca na reserva para não repetir · 404/410 = desinstalou: tira o celular da reserva · outro erro: tenta de novo daqui a 15 min.
const envios = $('🔐 Prepara os lembretes').all();
return $input.all().map((resp, i) => {
