  else if (st === 404 || st === 410) r.sub = null;
  else return null;
  return { json: { chave: e.chave, valor: JSON.stringify(r), ttl: Math.max(3600, Math.round((Date.parse(r.dia + 'T23:59:00-03:00') - Date.now()) / 1000)) + 60 * 86400 } };
}).filter(Boolean);

// a agenda responde na hora com os links; as IAs terminam os textos em segundo plano
