// Confere o formulário do dono e lê serviços, profissionais e horários POR REGRA (duração e preço não podem sair errados).
let b = $('🔔 Pedido de criação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const sem = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const slug = s => sem(s).replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 34);
const opcao = (v, lista, padrao) => lista.includes(Number(v)) ? Number(v) : padrao;
const crypto = require('crypto');
const erros = [];

// "Corte masculino - 30 min - R$ 35" · "Corte + barba | 1h | 55,00" · "Sobrancelha 15min R$10"
const servicos = String(b.servicos || '').split(/\n|;/).map(l => l.trim()).filter(Boolean).slice(0, 30).map((l, i) => {
  const dur = l.match(/(\d{1,3}(?:[.,]\d)?)\s*(h|hr|hora|horas|min|mins|minutos|m)\b/i);
  const preco = l.match(/R\$\s*([\d.]+(?:,\d{1,2})?)/i) || l.match(/(?:^|[\s|–—-])(\d{1,5}(?:,\d{2}|\.\d{2}))\s*$/);
  let nome = l;
  if (dur) nome = nome.replace(dur[0], ' ');
  if (preco) nome = nome.replace(preco[0], ' ');
  nome = limpa(nome.replace(/[|–—:]+/g, ' ').replace(/\s-\s|\s-$|^-\s/g, ' '), 50).replace(/\s*-\s*$/, '');
  let min = dur ? (/^h/i.test(dur[2]) ? Math.round(parseFloat(dur[1].replace(',', '.')) * 60) : parseInt(dur[1], 10)) : 30;
  min = Math.min(480, Math.max(15, Math.ceil(min / 15) * 15));  // a agenda trabalha em blocos de 15 min
  const valor = preco ? Number(preco[1].replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) || 0 : 0;
  return nome ? { k: 's' + (i + 1), nome, duracao: min, preco: Math.round(valor * 100) / 100 } : null;
}).filter(Boolean);
if (!servicos.length) erros.push('Liste pelo menos 1 serviço (ex.: Corte masculino - 30 min - R$ 35).');

// "Zé: corte, barba" (só esses serviços) · "Léo" (todos)
let profissionais = String(b.profissionais || '').split(/\n|;/).map(l => l.trim()).filter(Boolean).slice(0, 12).map((l, i) => {
  const [n, lista] = l.split(':');
  const nome = limpa(n, 30);
  let ks = servicos.map(s => s.k);
  if (lista && lista.trim()) {
    const pedidos = lista.split(/,|\be\b/).map(x => sem(x).trim()).filter(Boolean);
    const achados = servicos.filter(s => pedidos.some(p => sem(s.nome).includes(p) || p.includes(sem(s.nome))));
    if (achados.length) ks = achados.map(s => s.k);
  }
  return nome ? { k: 'p' + (i + 1), nome, servicos: ks } : null;
}).filter(Boolean);
if (!profissionais.length) profissionais = [{ k: 'p1', nome: 'Equipe', servicos: servicos.map(s => s.k) }];

// horário: um registro por dia da semana (0 = domingo), com pausa opcional
const min = h => +h.slice(0, 2) * 60 + +h.slice(3);
const hh = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
// tudo alinhado na marca de 15 min: as travas são blocos de 15 min e só se cruzam se começarem nas mesmas marcas
const hhmm = (v, sobe) => {
  if (!/^\d{1,2}:\d{2}$/.test(String(v || ''))) return '';
  const m = min(String(v).padStart(5, '0'));
  return m >= 0 && m <= 1440 ? hh(Math.min(1440, sobe ? Math.ceil(m / 15) * 15 : Math.floor(m / 15) * 15)).replace('24:00', '23:45') : '';
};
const horarios = {};
for (let d = 0; d < 7; d++) {
  const h = (b.horarios || {})[d] || {};
  const abre = hhmm(h.abre, true), fecha = hhmm(h.fecha, false), pi = hhmm(h.pausa_ini, false), pf = hhmm(h.pausa_fim, true);
  if (!h.aberto || !abre || !fecha || min(fecha) <= min(abre)) { horarios[d] = []; continue; }
  horarios[d] = pi && pf && min(pi) > min(abre) && min(pf) < min(fecha) && min(pf) > min(pi)
    ? [{ abre, fecha: pi }, { abre: pf, fecha }] : [{ abre, fecha }];
}
if (!Object.values(horarios).some(x => x.length)) erros.push('Marque pelo menos 1 dia de atendimento com horário de abrir e fechar.');

const dados = {
  nome: limpa(b.nome, 60), tipo: limpa(b.tipo, 40), servicos, profissionais, horarios,
  passo: opcao(b.passo, [15, 30, 60], 30), antecedencia_h: opcao(b.antecedencia_h, [0, 1, 2, 4, 12, 24], 2),
  dias_frente: opcao(b.dias_frente, [7, 14, 30, 60], 30), cancelar_ate_h: opcao(b.cancelar_ate_h, [0, 1, 2, 6, 12, 24], 2),
  regras: limpa(b.regras, 300),
  whatsapp: String(b.whatsapp || '').replace(/\D/g, '').slice(0, 15),
  instagram: limpa(b.instagram, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
  endereco: limpa(b.endereco, 200),
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '',
};
if (dados.nome.length < 2) erros.push('Digite o nome do negócio.');
if (dados.whatsapp && dados.whatsapp.length < 10) erros.push('O WhatsApp precisa ter DDD.');
if (dados.whatsapp.length >= 10 && dados.whatsapp.length <= 11) dados.whatsapp = '55' + dados.whatsapp;

const id = (slug(dados.nome) || 'agenda') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(6).toString('hex');
const base = String($('🔔 Pedido de criação (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
const DIAS = ['domingo', 'segunda', 'terça', 'quarta', 'quinta', 'sexta', 'sábado'];
