    <div class="bts" id="acoes"><button class="bt sec" id="bt-lembrete">🔔 Me lembrar no celular</button><button class="bt" id="bt-remarcar">🔁 Remarcar (escolher outro horário)</button>
    <button class="bt sec" id="bt-cancelar">❌ Cancelar</button></div>
    <p class="sub" id="prazo" hidden>Pelo link dá para cancelar ou remarcar até ${p.cancelar_ate_h} h antes. Agora, fale direto com a gente${p.whatsapp ? ' pelo WhatsApp' : ''}.</p></div></div>
  <div class="bts"><a class="bt sec" href="agendar">📅 Fazer outro agendamento</a>${p.whatsapp ? `<a class="bt sec" href="https://wa.me/${p.whatsapp}" target="_blank" rel="noopener">💬 Falar no WhatsApp</a>` : ''}</div></main>
<div id="toast" role="status" aria-live="polite"></div>
<script>(${tela.toString()})(${JSON.stringify({ id: p.id, vapid: p.vapid.publica }).replace(/</g, '\\u003c')});</script>
</body></html>`;
return [{ json: { codigo: 200, html } }];

// Monta o service worker da agenda: só recebe os lembretes e o aviso de vaga, e abre a página certa ao tocar.
const id = String(($('🔔 Pedido do motor da agenda (GET)').first().json.params || {}).id || '').replace(/[^a-z0-9-]/g, '');
function motor() {
  self.addEventListener('install', function () { self.skipWaiting(); });
  self.addEventListener('activate', function (e) { e.waitUntil(self.clients.claim()); });
  self.addEventListener('push', function (e) {
    var d = {};
    try { d = e.data ? e.data.json() : {}; } catch (x) { d = { texto: e.data ? e.data.text() : '' }; }
    e.waitUntil(self.registration.showNotification(d.titulo || 'Lembrete do seu horário', { body: d.texto || '', tag: d.tag || 'agenda', data: { url: d.url || 'agendar' } }));
  });
  self.addEventListener('notificationclick', function (e) {
    e.notification.close();
    var alvo = new URL(e.notification.data && e.notification.data.url || 'agendar', self.registration.scope).href;
    e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (ws) {
      for (var i = 0; i < ws.length; i++) { if (ws[i].url.indexOf(self.registration.scope) === 0 && 'focus' in ws[i]) { ws[i].navigate(alvo); return ws[i].focus(); } }
      return self.clients.openWindow(alvo);
    }));
  });
}
return [{ json: { js: id ? `(${motor.toString()})();` : '/* agenda inválida */' } }];

// Lê o pedido da página de agendar (ou da página da reserva) e monta as chaves do Redis que precisam ser lidas.
let b = $('🔔 Pedido da agenda (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f<>{}]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const ACOES = ['horarios', 'reservar', 'reserva', 'cancelar', 'lembrar', 'espera'];
const id = /^[a-z0-9-]{4,60}$/.test(String(b.id || '')) ? String(b.id) : '';
const codigo = /^r\d{8}[a-f0-9]{4}$/.test(String(b.codigo || '')) ? String(b.codigo) : '';
let dia = /^\d{4}-\d{2}-\d{2}$/.test(String(b.dia || '')) ? String(b.dia) : '';
if (codigo) dia = `${codigo.slice(1, 5)}-${codigo.slice(5, 7)}-${codigo.slice(7, 9)}`;  // o código da reserva carrega o dia
let fone = String(b.fone || '').replace(/\D/g, '').slice(0, 13);
if (fone.length >= 10 && fone.length <= 11) fone = '55' + fone;
return [{ json: { acao: ACOES.includes(b.acao) && id ? b.acao : 'invalida', id, codigo, dia, token: String(b.token || '').slice(0, 40),
  servico: /^s\d{1,2}$/.test(String(b.servico || '')) ? b.servico : '', prof: /^(p\d{1,2}|\*)$/.test(String(b.prof || '')) ? b.prof : '*',
  hora: /^\d{2}:\d{2}$/.test(String(b.hora || '')) ? b.hora : '', nome: limpa(b.nome, 40), fone, sub: b.sub && typeof b.sub === 'object' ? b.sub : null,
  k_programa: 'ag:' + (id || '-'), k_travas: id && dia ? `agl:${id}:*:${dia}:*` : 'agl:-:nada',
  k_reserva: id && codigo ? `agr:${id}:${dia}:${codigo}` : 'agr:-:nada', k_espera: id && dia ? `agw:${id}:${dia}:*` : 'agw:-:nada' } }];

// Horários livres (mesma conta na página, na reserva, no painel e na sugestão de promoção).
// Brasil sem horário de verão: Brasília = UTC-3 fixo.
const AG_BLOCO = 15;
const agMin = h => +String(h).slice(0, 2) * 60 + +String(h).slice(3, 5);
const agHH = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const agSemana = dia => new Date(dia + 'T12:00:00Z').getUTCDay();          // 0 = domingo
const agMs = (dia, hora) => Date.parse(`${dia}T${hora}:00-03:00`);
const agHoje = ms => new Date(ms - 3 * 3600000).toISOString().slice(0, 10);
const agSoma = (dia, n) => new Date(Date.parse(dia + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
// blocos de 15 min que um atendimento ocupa ("0900", "0915"...)
function agBlocos(hora, duracao) { const m = agMin(hora), r = []; for (let x = m; x < m + duracao; x += AG_BLOCO) r.push(agHH(x).replace(':', '')); return r; }
// ocupados: { "<prof>": Set("0900", ...) } lidos das travas do dia
function agOcupados(travas, id, dia) {
  const o = {};
  Object.keys(travas || {}).forEach(k => {
    const m = k.match(/^agl:([a-z0-9-]+):(p\d+):(\d{4}-\d{2}-\d{2}):(\d{4})$/);
    if (m && m[1] === id && m[3] === dia && Number(travas[k]) >= 1) (o[m[2]] = o[m[2]] || new Set()).add(m[4]);
  });
  return o;
}
// começos livres para um profissional: dentro do expediente, cabendo a duração inteira, sem pisar em bloco ocupado e com a antecedência mínima
function agLivres(prog, pk, dia, duracao, ocupados, agoraMs) {
  const oc = ocupados[pk] || new Set(), saida = [];
  if (dia < agHoje(agoraMs) || dia > agSoma(agHoje(agoraMs), prog.dias_frente)) return saida;
  for (const f of prog.horarios[agSemana(dia)] || []) {
    for (let m = agMin(f.abre); m + duracao <= agMin(f.fecha); m += prog.passo) {
      if (agMs(dia, agHH(m)) < agoraMs + prog.antecedencia_h * 3600000) continue;
      if (agBlocos(agHH(m), duracao).every(b => !oc.has(b))) saida.push(agHH(m));
    }
  }
  return saida;
}
// quem faz o serviço
const agProfsDo = (prog, sk) => prog.profissionais.filter(p => p.servicos.includes(sk));

// O coração da agenda: horários livres, reserva (com trava contra agendamento duplo), cancelamento no prazo, lembrete e lista de espera.
const crypto = require('crypto');
const P = $('🧩 Lê o pedido da agenda').first().json;
let prog = null, res = null;
try { prog = JSON.parse($('📖 Lê a agenda (API)').first().json.programa || 'null'); } catch (e) {}
try { res = JSON.parse($('📖 Lê a reserva').first().json.reserva || 'null'); } catch (e) {}
const travas = $('🗂️ Lê as travas do dia').first().json || {};
const agora = Date.now();
const sets = [], solta = [], somas = [], travar = [];
const sai = (rota, codigo, corpo, extra = {}) => [{ json: { rota, codigo, resposta: JSON.stringify(corpo), sets, solta, somas, travar, id: P.id, hoje: agHoje(agora), ...extra } }];
const erro = (msg, codigo = 400, extra = {}) => sai('responder', codigo, { ok: false, erro: msg, ...extra });
if (!prog) return erro('Agenda não encontrada. Confira o link.', 404);
if (P.acao === 'invalida') return erro('Pedido inválido.');

const hmac = t => crypto.createHmac('sha256', prog.segredo).update(t).digest('hex');
const tokenDe = c => hmac('res:' + c).slice(0, 20);
const serv = prog.servicos.find(s => s.k === P.servico);
const ocup = agOcupados(travas, prog.id, P.dia);
const ateFimDoDia = dia => Math.max(3600, Math.round((agMs(dia, '23:59') - agora) / 1000));
const podeCancelar = r => r.status === 'confirmada' && agMs(r.dia, r.hora) - agora >= prog.cancelar_ate_h * 3600000;
const publica = r => ({ codigo: r.codigo, dia: r.dia, hora: r.hora, fim: r.fim, servico: r.servico_nome, servico_k: r.servico, duracao: r.duracao, preco: r.preco, prof: r.prof_nome,
  nome: r.cliente.nome, status: r.status, lembrete: !!r.sub });
// a chave do celular tem de ser um ponto válido da curva P-256 (chave quebrada derrubaria os lembretes dos outros)
function subOk(s) {
  if (!s || typeof s.endpoint !== 'string' || !/^https:\/\//.test(s.endpoint) || s.endpoint.length > 1000 || !s.keys) return null;
  try {
    const b = t => Buffer.from(String(t).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
    const e = crypto.createECDH('prime256v1'); e.generateKeys(); e.computeSecret(b(s.keys.p256dh));
    return b(s.keys.auth).length === 16 ? { endpoint: s.endpoint, keys: { p256dh: s.keys.p256dh, auth: s.keys.auth } } : null;
  } catch (e) { return null; }
}

if (P.acao === 'horarios') {
  if (!serv || !P.dia) return erro('Escolha o serviço e o dia.');
  const mapa = {};
  agProfsDo(prog, serv.k).filter(p => P.prof === '*' || p.k === P.prof)
    .forEach(p => agLivres(prog, p.k, P.dia, serv.duracao, ocup, agora).forEach(h => { (mapa[h] = mapa[h] || []).push(p.k); }));
  return sai('responder', 200, { ok: true, dia: P.dia, servico: serv.k, horarios: Object.keys(mapa).sort().map(h => ({ hora: h, profs: mapa[h] })) });
}

if (P.acao === 'reservar') {
  if (!serv) return erro('Escolha um serviço.');
  if (!P.dia || !P.hora) return erro('Escolha o dia e o horário.');
  if (P.nome.length < 2) return erro('Digite seu nome.');
  if (P.fone.length < 12) return erro('Digite seu WhatsApp com DDD.');
  // "qualquer um": quem tem menos atendimentos no dia vem primeiro (divide o trabalho)
  const candidatos = agProfsDo(prog, serv.k).filter(p => P.prof === '*' || p.k === P.prof)
    .sort((a, b) => (ocup[a.k] ? ocup[a.k].size : 0) - (ocup[b.k] ? ocup[b.k].size : 0));
  const prof = candidatos.find(p => agLivres(prog, p.k, P.dia, serv.duracao, ocup, agora).includes(P.hora));
  if (!prof) return erro('Esse horário acabou de ser ocupado. Escolha outro.', 409, { ocupado: true });
  const codigo = 'r' + P.dia.replace(/-/g, '') + crypto.randomBytes(2).toString('hex');
  const r = { codigo, dia: P.dia, hora: P.hora, fim: agHH(agMin(P.hora) + serv.duracao), servico: serv.k, servico_nome: serv.nome, duracao: serv.duracao, preco: serv.preco,
    prof: prof.k, prof_nome: prof.nome, cliente: { nome: P.nome, fone: P.fone }, status: 'confirmada', criado: agora, sub: subOk(P.sub), lembrou24: false, lembrou2: false };
  const ttl = ateFimDoDia(P.dia) + 86400;
  agBlocos(P.hora, serv.duracao).forEach(b => travar.push({ chave: `agl:${prog.id}:${prof.k}:${P.dia}:${b}`, ttl }));
  sets.push({ chave: `agr:${prog.id}:${P.dia}:${codigo}`, valor: JSON.stringify(r), ttl: ateFimDoDia(P.dia) + 60 * 86400 });
  somas.push(`agst:${prog.id}:reservas:${agHoje(agora)}`);
  return sai('travar', 200, { ok: true, codigo, token: tokenDe(codigo), reserva: publica(r) });
}

if (P.acao === 'espera') {
  if (!serv || !P.dia) return erro('Escolha o serviço e o dia.');
  if (P.nome.length < 2 || P.fone.length < 12) return erro('Digite seu nome e o WhatsApp com DDD.');
  const e = { nome: P.nome, fone: P.fone, servico: serv.k, servico_nome: serv.nome, prof: P.prof, dia: P.dia, criado: agora, sub: subOk(P.sub) };
  sets.push({ chave: `agw:${prog.id}:${P.dia}:${crypto.randomBytes(3).toString('hex')}`, valor: JSON.stringify(e), ttl: ateFimDoDia(P.dia) });
  somas.push(`agst:${prog.id}:espera:${agHoje(agora)}`);
  return sai('gravar', 200, { ok: true, espera: true, aviso: !!e.sub });
}

// daqui para baixo é a página da reserva: precisa do código e do token do link
if (!res || !P.codigo || P.token !== tokenDe(P.codigo)) return erro('Reserva não encontrada. Confira o link que você recebeu.', 404);
if (P.acao === 'reserva') return sai('responder', 200, { ok: true, reserva: publica(res), pode_cancelar: podeCancelar(res), cancelar_ate_h: prog.cancelar_ate_h });

if (P.acao === 'cancelar') {
  if (res.status !== 'confirmada') return erro('Essa reserva já está ' + res.status + '.');
  if (!podeCancelar(res)) return erro(`Pelo link, dá para cancelar até ${prog.cancelar_ate_h} h antes. Fale com a gente pelo WhatsApp.`);
  res.status = 'cancelada'; res.cancelada_por = 'cliente'; res.cancelada_em = agora;
  sets.push({ chave: `agr:${prog.id}:${res.dia}:${res.codigo}`, valor: JSON.stringify(res), ttl: ateFimDoDia(res.dia) + 60 * 86400 });
  agBlocos(res.hora, res.duracao).forEach(b => solta.push(`agl:${prog.id}:${res.prof}:${res.dia}:${b}`));
  somas.push(`agst:${prog.id}:cancelamentos:${agHoje(agora)}`);
  return sai('gravar', 200, { ok: true, reserva: publica(res) }, { liberou: { dia: res.dia, hora: res.hora, prof: res.prof, prof_nome: res.prof_nome, servico: res.servico }, prog });
}

if (P.acao === 'lembrar') {
  const s = subOk(P.sub);
  if (!s) return erro('Não deu para ligar o lembrete neste celular.');
  res.sub = s;
  sets.push({ chave: `agr:${prog.id}:${res.dia}:${res.codigo}`, valor: JSON.stringify(res), ttl: ateFimDoDia(res.dia) + 60 * 86400 });
  return sai('gravar', 200, { ok: true, reserva: publica(res) });
}
return erro('Pedido inválido.');

const d = $('📅 Decide a agenda').first().json;
const l = (d.travar || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : []).map(x => ({ json: x }));

// Cada bloco de 15 min foi travado com INCR: 1 = é nosso; mais que 1 = alguém pegou antes (ou no mesmo instante).
const D = $('📅 Decide a agenda').first().json;
const r = $input.all().map((it, i) => ({ chave: (D.travar[i] || {}).chave, n: Number(Object.values(it.json || {})[0]) }));
if (r.length === D.travar.length && r.every(x => x.n === 1)) return [{ json: { ok: true } }];
// desfaz só os blocos que pegamos (n = 1); os outros são de quem chegou antes
return [{ json: { ok: false, soltar: r.filter(x => x.n === 1 && x.chave).map(x => x.chave) } }];

const d = $('📅 Decide a agenda').first().json;
const l = (d.sets || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : []).map(x => ({ json: x }));

const d = $('📅 Decide a agenda').first().json;
const l = (d.somas || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : [{ chave: `agst:${d.id}:uso:${d.hoje}` }]).map(x => ({ json: x }));

const d = $('📅 Decide a agenda').first().json;
const l = (d.sets || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : []).map(x => ({ json: x }));

const d = $('📅 Decide a agenda').first().json;
const l = (d.solta || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : [{ chave: '<SEGREDO_REMOVIDO>' }]).map(x => ({ json: x }));

const d = $('📅 Decide a agenda').first().json;
const l = (d.somas || []).map(x => typeof x === 'string' ? { chave: x } : x);
return (l.length ? l : [{ chave: `agst:${d.id}:uso:${d.hoje}` }]).map(x => ({ json: x }));

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
function criptografa(sub, texto) {
  const cr = require('crypto');
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = cr.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = cr.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(cr.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = cr.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}
function vapid(prog, endpoint) {
  const cr = require('crypto');
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla); o Code node não tem URL(), então recorto o texto
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = cr.sign('sha256', Buffer.from(cab + '.' + corpo), { key: cr.createPrivateKey({ key: prog.vapid.privada, format: 'jwk' }), dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${prog.vapid.publica}`;
}
// {nome} = primeiro nome do cliente · {faltam} = carimbos que faltam para o prêmio
const pers = (t, c, prog) => String(t || '').replace(/\{nome\}/g, String(c.nome || '').split(' ')[0]).replace(/\{faltam\}/g, Math.max(1, prog.meta - c.carimbos));

// Abriu um horário (alguém cancelou): avisa no celular quem entrou na lista de espera daquele dia.
let D = null, esp = {};
try { D = $('📅 Decide a agenda').first().json; esp = $('🗂️ Lê a lista de espera').first().json || {}; }
catch (e) { D = $('🔑 Confere a chave e decide (agenda)').first().json; esp = $('🗂️ Lê a lista de espera (dono)').first().json || {}; }
const lib = D.liberou, prog = D.prog;
if (!lib || !prog) return [];
const dm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
const saida = [];
Object.entries(esp).filter(([k]) => k.startsWith(`agw:${prog.id}:${lib.dia}:`)).forEach(([k, v]) => {
  let e = null;
  try { e = JSON.parse(v); } catch (x) {}
  if (!e || !e.sub) return;
  try {
    saida.push({ json: { chave: k, endpoint: e.sub.endpoint, autorizacao: vapid(prog, e.sub.endpoint) },
      binary: { corpo: { data: criptografa(e.sub, JSON.stringify({ titulo: '🔔 Abriu um horário!', texto: `${dm(lib.dia)} às ${lib.hora} com ${lib.prof_nome}. Toque para agendar antes que alguém pegue.`,
        url: `agendar?d=${lib.dia}&s=${e.servico}`, tag: 'vaga-' + lib.dia })).toString('base64'), mimeType: 'application/octet-stream', fileName: 'aviso.bin' } } });
  } catch (x) {}
});
return saida;

// Lê o pedido do painel do dono (só vale com a chave do painel, conferida no próximo passo).
let b = $('🔔 Pedido do dono (agenda POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const id = /^[a-z0-9-]{4,60}$/.test(String(b.id || '')) ? String(b.id) : '';
const codigo = /^r\d{8}[a-f0-9]{4}$/.test(String(b.codigo || '')) ? String(b.codigo) : '';
const dia = codigo ? `${codigo.slice(1, 5)}-${codigo.slice(5, 7)}-${codigo.slice(7, 9)}` : '';
return [{ json: { acao: ['marcar', 'cancelar', 'sugerir'].includes(b.acao) ? b.acao : 'invalida', id, codigo, chave: String(b.chave || '').slice(0, 40),
  status: String(b.status || ''), ideia: String(b.ideia || '').replace(/[<>{}]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 200),
  k_programa: 'ag:' + (id || '-'), k_reserva: id && codigo ? `agr:${id}:${dia}:${codigo}` : 'agr:-:nada',
  k_espera: id && dia ? `agw:${id}:${dia}:*` : 'agw:-:nada', k_travas: id ? `agl:${id}:*` : 'agl:-:nada' } }];

// Horários livres (mesma conta na página, na reserva, no painel e na sugestão de promoção).
// Brasil sem horário de verão: Brasília = UTC-3 fixo.
const AG_BLOCO = 15;
const agMin = h => +String(h).slice(0, 2) * 60 + +String(h).slice(3, 5);
const agHH = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const agSemana = dia => new Date(dia + 'T12:00:00Z').getUTCDay();          // 0 = domingo
const agMs = (dia, hora) => Date.parse(`${dia}T${hora}:00-03:00`);
