  const texto_ia = `NEGÓCIO: ${prog.nome} (${prog.tipo || 'serviços'})${prog.endereco ? ' · ' + prog.endereco : ''}
SERVIÇOS (nome, duração, preço): ${prog.servicos.map(s => `${s.nome} (${s.duracao} min${s.preco ? ', R$ ' + s.preco.toFixed(2).replace('.', ',') : ''})`).join('; ')}
PROFISSIONAIS: ${prog.profissionais.map(p => p.nome).join(', ')}
HORÁRIOS VAZIOS NOS PRÓXIMOS 7 DIAS:
${linhas.join('\n') || '(nenhum: a agenda está cheia)'}
