  const botaoEscuro = contraste(C, '#1b1b1d') < 3 ? legivel('#1b1b1d', [255, 255, 255], 8) : C;
  return { C, texto: lum(C) > 0.45 ? '#111111' : '#ffffff', C2: mistura(C, [0, 0, 0], 0.35), CL: mistura(C, [255, 255, 255], 0.88), CLd: mistura(C, [0, 0, 0], 0.6),
    claro: legivel('#ffffff', [0, 0, 0]), escuro: legivel('#1b1b1d', [255, 255, 255]), botaoEscuro, textoBotaoEscuro: lum(botaoEscuro) > 0.45 ? '#111111' : '#ffffff',
    barraClaro: legivel('#ffffff', [0, 0, 0], 3), barraEscuro: legivel('#1b1b1d', [255, 255, 255], 3) };
}
