  try { return JSON.parse(v); } catch (e) { return null; }
}).filter(Boolean);
const espera = Object.entries($('🗂️ Lê a lista de espera (painel)').first().json || {}).filter(([kk]) => kk.startsWith(`agw:${p.id}:${dia}:`)).map(([, v]) => {
