const dm = d => d.slice(8, 10) + '/' + d.slice(5, 7);
const valida = r => r.status !== 'cancelada';
const receita = l => l.filter(r => r.status === 'confirmada' || r.status === 'compareceu').reduce((a, r) => a + (Number(r.preco) || 0), 0);

// o dia
