const proximos = reservas.filter(r => r.dia >= hoje && r.dia <= agSoma(hoje, 30)).sort((a, b) => (a.dia + a.hora).localeCompare(b.dia + b.hora))
  .map(r => ({ codigo: r.codigo, dia: r.dia, hora: r.hora, cliente: r.cliente.nome, fone: r.cliente.fone, servico: r.servico_nome, prof: r.prof_nome, preco: r.preco, status: r.status, lembrete: !!r.sub }));
const fone = f => { const s = String(f || '').replace(/^55/, ''); return s.length === 11 ? `(${s.slice(0, 2)}) ${s.slice(2, 7)}-${s.slice(7)}` : s; };
const ST = { confirmada: '✅ confirmada', cancelada: '❌ cancelada', compareceu: '🎉 compareceu', faltou: '⚠️ faltou' };

function painel(D) {
  var el = function (s) { return document.querySelector(s); };
  function api(d) {
    return fetch('/webhook/agenda-dono', { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: D.id, chave: D.chave }, d)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão.' }; });
  }
  function toast(t) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, 4000); }
  // ações em cada atendimento do dia
  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-acao]'); if (!b) return;
    var acao = b.dataset.acao, codigo = b.dataset.codigo;
    if (acao === 'cancelar' && !confirm('Cancelar este horário? Ele fica livre e quem está na lista de espera é avisado.')) return;
    b.disabled = true;
    api(acao === 'cancelar' ? { acao: 'cancelar', codigo: codigo } : { acao: 'marcar', codigo: codigo, status: acao }).then(function (r) {
      if (!r.ok) { b.disabled = false; toast('⚠️ ' + r.erro); return; }
      toast(acao === 'cancelar' ? 'Cancelado. O horário está livre de novo.' : 'Marcado: ' + r.status);
      setTimeout(function () { location.reload(); }, 900);
    });
  });
  // tabela dos próximos 30 dias: ordena, filtra e baixa CSV
  var COLS = [['dia', 'Dia'], ['hora', 'Hora'], ['cliente', 'Cliente'], ['fone', 'WhatsApp'], ['servico', 'Serviço'], ['prof', 'Profissional'], ['preco', 'Preço'], ['status', 'Situação']];
  var ordem = { campo: 'dia', dir: 1 }, busca = '';
  function linhas() {
    var qq = busca.toLowerCase();
    return D.proximos.filter(function (l) { return !qq || (l.cliente + ' ' + l.fone + ' ' + l.servico + ' ' + l.prof + ' ' + l.status).toLowerCase().indexOf(qq) > -1; })
      .sort(function (a, b) { var x = ordem.campo === 'dia' ? a.dia + a.hora : a[ordem.campo], y = ordem.campo === 'dia' ? b.dia + b.hora : b[ordem.campo]; return (x > y ? 1 : x < y ? -1 : 0) * ordem.dir; });
  }
  function tabela() {
    var ls = linhas();
    el('#thead').innerHTML = '<tr>' + COLS.map(function (c) { return '<th><button data-campo="' + c[0] + '">' + c[1] + (ordem.campo === c[0] ? (ordem.dir > 0 ? ' ▲' : ' ▼') : '') + '</button></th>'; }).join('') + '</tr>';
    el('#tbody').innerHTML = ls.map(function (l) {
      return '<tr><td>' + l.dia.slice(8, 10) + '/' + l.dia.slice(5, 7) + '</td><td>' + l.hora + '</td><td>' + l.cliente.replace(/[<>&]/g, '') + '</td><td><a href="https://wa.me/' + l.fone + '" target="_blank" rel="noopener">' + D.fone(l.fone) + '</a></td><td>'
        + l.servico.replace(/[<>&]/g, '') + '</td><td>' + l.prof.replace(/[<>&]/g, '') + '</td><td>' + (l.preco ? 'R$ ' + Number(l.preco).toFixed(2).replace('.', ',') : '—') + '</td><td>' + (D.st[l.status] || l.status) + '</td></tr>';
    }).join('') || '<tr><td colspan="8" class="vazio">Nenhum agendamento nos próximos 30 dias.</td></tr>';
    el('#qtd').textContent = ls.length + ' de ' + D.proximos.length + ' agendamentos';
  }
  D.fone = function (f) { var s = String(f || '').replace(/^55/, ''); return s.length === 11 ? '(' + s.slice(0, 2) + ') ' + s.slice(2, 7) + '-' + s.slice(7) : s; };
  el('#thead').addEventListener('click', function (e) { var b = e.target.closest('[data-campo]'); if (!b) return; ordem = { campo: b.dataset.campo, dir: ordem.campo === b.dataset.campo ? -ordem.dir : 1 }; tabela(); });
  el('#busca').addEventListener('input', function () { busca = this.value; tabela(); });
  el('#csv').addEventListener('click', function () {
    var qv = function (v) { v = String(v == null ? '' : v); return /[",;\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
    var corpo = ['dia;hora;cliente;whatsapp;servico;profissional;preco;situacao'].concat(linhas().map(function (l) { return [l.dia, l.hora, l.cliente, l.fone, l.servico, l.prof, l.preco, l.status].map(qv).join(';'); }));
    var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['\ufeff' + corpo.join('\n')], { type: 'text/csv;charset=utf-8' })); a.download = 'agenda-' + D.id + '.csv'; a.click();
  });
  tabela();
  // promoção para os horários vazios (IA)
  el('#form-promo').addEventListener('submit', function (e) {
    e.preventDefault();
    var b = el('#bt-promo'); b.disabled = true; b.textContent = '⏳ Pensando…';
    api({ acao: 'sugerir', ideia: el('#ideia').value }).then(function (r) {
      b.disabled = false; b.textContent = '✨ Sugerir promoção';
      if (!r.ok) { el('#promo').innerHTML = '<p class="erro">⚠️ ' + (r.erro || 'A IA não respondeu.') + '</p>'; return; }
      var esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
      el('#promo').innerHTML = '<p><b>' + esc(r.titulo) + '</b></p>'
        + '<p class="rot">Para o WhatsApp (status ou lista)</p><pre id="p-wa">' + esc(r.whatsapp) + '</pre><div class="bts"><button class="bt" data-copiar="#p-wa">📋 Copiar</button><a class="bt" target="_blank" rel="noopener" href="https://wa.me/?text=' + encodeURIComponent(r.whatsapp) + '">💬 Abrir no WhatsApp</a></div>'
        + '<p class="rot">Para o Instagram</p><pre id="p-ig">' + esc(r.instagram) + '</pre><div class="bts"><button class="bt" data-copiar="#p-ig">📋 Copiar</button></div>'
        + (r.oferta ? '<p class="rot">💡 Ideia de oferta (só para você decidir)</p><p>' + esc(r.oferta) + '</p>' : '')
        + (r.problemas && r.problemas.length ? '<p class="sub">🔍 A revisora ajustou: ' + esc(r.problemas.join(' · ')) + '</p>' : '');
    });
  });
  document.addEventListener('click', function (e) { var b = e.target.closest('[data-copiar]'); if (!b) return; navigator.clipboard.writeText(el(b.dataset.copiar).textContent).then(function () { b.textContent = '✅ Copiado'; }); });
  var qr = qrcode(0, 'M'); qr.addData(D.agendar); qr.make();
  el('#qr').innerHTML = qr.createSvgTag({ cellSize: 6, margin: 2, scalable: true });
  el('#qr-cartaz').innerHTML = el('#qr').innerHTML;
  el('#imprimir').addEventListener('click', function () { window.print(); });
}

